import { defineConfig } from "vitest/config";

export default defineConfig({
  test: {
    globals: true,
    environment: "node",
    include: ["tests/**/*.test.ts"],
    coverage: {
      provider: "v8",
      include: ["src/**/*.ts"],
      // server.ts is the process entrypoint (starts Fastify, binds ports);
      // it is exercised by running the app, not by unit tests.
      // src/generated/prisma/** is Prisma-generated client code, not
      // hand-written logic; it is regenerated by `prisma generate` and
      // covered implicitly by every test that exercises the repositories.
      // runnerTypes.ts is a pure TypeScript type-declarations file (interfaces
      // only, no runtime statements); it compiles to an empty module, so v8
      // coverage has nothing to instrument and the file is not testable.
      exclude: ["src/server.ts", "src/generated/prisma/**", "src/runtime/runnerTypes.ts"],
      reporter: ["text", "json-summary", "html"],
      reportsDirectory: "coverage",
    },
  },
});
